for (const item of allItems) { const data = item.json; const query = data.query || ''; (data.shorts || []).forEach(s => allShorts.push({ video_id: s.video_id || '', url: s.url || '', title: s.title || 'No title', channel_id: s.channel_id || null, channel_title: s.channel_title || null, duration: s.duration || null, description: s.description || null, search_query: s.search_query || null, theme: data.theme || s.theme || '', all_queries: data.all_queries || s.all_queries || [], view_count: s.view_count || null, outlier_score: s.outlier_score !== undefined ? s.outlier_score : null, engagement_rate: s.engagement_rate !== undefined ? s.engagement_rate : null })); }
const uniqMap = {};
for (const s of allShorts) { if (!s.video_id) continue; if (!uniqMap[s.video_id]) { uniqMap[s.video_id] = s; } else { const existing = uniqMap[s.video_id]; for (const k in s) { if ((existing[k] === null || existing[k] === undefined || existing[k] === '') && s[k]) { existing[k] = s[k]; } } } }
const uniqueShorts = Object.values(uniqMap);
return uniqueShorts.length > 0 ? [{ json: { shorts: uniqueShorts } }] : [{ json: { shorts: [] } }];

// Build JSON file from model output and attach as binary
