return items.map(item => { const j = item.json; let aiText = ''; if (j.output && Array.isArray(j.output) && j.output[0].content && Array.isArray(j.output[0].content)) aiText = j.output[0].content[0].text || ''; else if (j.content && Array.isArray(j.content)) aiText = j.content[0]?.text || ''; else if (j.text) aiText = j.text; else if (j.message?.content) aiText = j.message.content; if (typeof aiText !== 'string') aiText = JSON.stringify(aiText || ''); let parsed = null; const match = aiText.match(/\\{[\\s\\S]*\\}/); if (match) { try { parsed = JSON.parse(match[0]); } catch(e) { parsed = match[0]; } } else { try { parsed = JSON.parse(aiText); } catch(e) { parsed = aiText; } } const fileContent = typeof parsed === 'string' ? parsed : JSON.stringify(parsed, null, 2); const fileName = (j.video_id || 'analysis') + '_' + new Date().toISOString().replace(/[:.]/g,'-') + '.json'; const base64 = Buffer.from(fileContent, 'utf-8').toString('base64'); return { json: { video_id: j.video_id || null }, binary: { analysis_file: { data: base64, mimeType: 'application/json', fileName: fileName } } }; });

