// runOnceForAllItems: pairs LLM outputs with original shorts from Merge Transcript by index.
// Handles both OpenAI node output and Google chainLlm output formats.
const llmOutputs = $input.all();
const shorts = $('Split Shorts').all();

return llmOutputs.map(function(item, i) {
    const j = item.json;
    const short = shorts[i] ? shorts[i].json : {};

    // Extract text from various LLM output structures
    let aiText = '';
    if (j.output && Array.isArray(j.output) && j.output[0]?.content && Array.isArray(j.output[0].content)) {
        // OpenAI node format
        aiText = j.output[0].content[0].text || '';
    } else if (j.content && Array.isArray(j.content)) {
        aiText = j.content[0]?.text || '';
    } else if (j.text) {
        // chainLlm (Google Gemini) format
        aiText = j.text;
    } else if (j.message?.content) {
        aiText = j.message.content;
    }

    if (typeof aiText !== 'string') {
        aiText = JSON.stringify(aiText || '');
    }

    let score = {};
    const match = aiText.match(/\{[\s\S]*\}/);
    if (match) {
        try { score = JSON.parse(match[0]); } catch(e) {}
    }

    return {
        json: {
            video_id: short.video_id || '',
            url: short.url || '',
            title: short.title || '',
            channel_title: short.channel_title || '',
            duration: short.duration || null,
            description: short.description || null,
            theme: short.theme || '',
            view_count: short.view_count || null,
            outlier_score: short.outlier_score !== undefined ? short.outlier_score : null,
            engagement_rate: short.engagement_rate !== undefined ? short.engagement_rate : null,
            score: typeof score.score === 'number' ? score.score : 0,
            reason: score.reason || ''
        }
    };
});
